    adj: Dict[str, Dict[str, int]], 
    start: str, 
    end: str, 
    block_u: str, 
    block_v: str
) -> bool:
    if start == end:
        return True

    visited: Set[str] = {start}
    queue = [start]

    while queue:
        node = queue.pop(0)
        for neighbor in adj.get(node, {}):
            if (node == block_u and neighbor == block_v) or (node == block_v and neighbor == block_u):
                continue

            if neighbor == end:
                return True

            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return False
